<?php require 'includes/init.php'; $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $u=Passenger::login(trim($_POST['email']??''),$_POST['password']??''); if($u){session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'name'=>$u['full_name'],'role'=>$u['role']];$next=$_GET['next']??'';header('Location: '.($u['role']==='admin'?'admin.php':(preg_match('/^[\w\/.\-?=&%]+$/',$next)&&strpos($next,'//')===false?$next:'dashboard.php')));exit;} $err='Wrong email or password.';} include 'includes/header.php'; ?>
